package com.dtm.platform.controller;import com.dtm.platform.service.*;import com.dtm.platform.dto.*;import org.springframework.web.bind.annotation.*;import jakarta.validation.Valid;import org.springframework.security.access.prepost.PreAuthorize;import java.util.*;
@RestController @RequestMapping("/api/v1") public class ContentController {
 private final ContentService content;public ContentController(ContentService content){this.content=content;}
 @GetMapping("/{resource:projects|technologies|skills|experience|education|companies|services|articles|categories|resume|timeline|profile}") public PageDto<ContentDto> list(@PathVariable String resource,@RequestParam(defaultValue="")String q,@RequestParam(required=false)String category,@RequestParam(required=false)String status,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="24")int size,@RequestParam(defaultValue="sortOrder,asc")String sort){return content.list(resource,q,category,status,page,size,sort,false);}
 @GetMapping("/{resource:projects|technologies|skills|experience|education|companies|services|articles|categories|resume|timeline|profile}/{key}") public ContentDto detail(@PathVariable String resource,@PathVariable String key){return content.detail(resource,key,false);}
 @GetMapping("/search") public List<ContentDto> search(@RequestParam String q){return content.search(q.length()>120?q.substring(0,120):q);}
 @GetMapping("/admin/{resource}") @PreAuthorize("hasAnyRole('ADMIN','EDITOR')") public PageDto<ContentDto> admin(@PathVariable String resource,@RequestParam(defaultValue="")String q,@RequestParam(required=false)String category,@RequestParam(required=false)String status,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="24")int size,@RequestParam(defaultValue="sortOrder,asc")String sort){return content.list(resource,q,category,status,page,size,sort,true);}
 @GetMapping("/admin/{resource}/{key}") @PreAuthorize("hasAnyRole('ADMIN','EDITOR')") public ContentDto adminDetail(@PathVariable String resource,@PathVariable String key){return content.detail(resource,key,true);}
 @PostMapping("/admin/{resource}") @PreAuthorize("hasRole('ADMIN') or (hasRole('EDITOR') and #resource != 'settings' and #resource != 'profile')") @ResponseStatus(org.springframework.http.HttpStatus.CREATED) public ContentDto create(@PathVariable String resource,@Valid @RequestBody ContentInput input){return content.save(resource,null,input);}
 @RequestMapping(value="/admin/{resource}/{key}",method={RequestMethod.PUT,RequestMethod.PATCH}) @PreAuthorize("hasRole('ADMIN') or (hasRole('EDITOR') and #resource != 'settings' and #resource != 'profile')") public ContentDto update(@PathVariable String resource,@PathVariable String key,@Valid @RequestBody ContentInput input){return content.save(resource,key,input);}
 @DeleteMapping("/admin/{resource}/{key}") @PreAuthorize("hasRole('ADMIN')") @ResponseStatus(org.springframework.http.HttpStatus.NO_CONTENT) public void delete(@PathVariable String resource,@PathVariable String key){content.delete(resource,key);}
}
